const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);
const firstAttachmentKey = binaryKeys[0] || null;

const subject = String(json.subject || '').trim();
const fromEmail = String(json.from || (json.from && json.from.text) || (json.headers && json.headers.from) || '').trim();
const fromName = String((json.from && json.from.name) || fromEmail.split('@')[0] || 'Client').trim();

const typeTriggers = [
  ['diplome', 'Diplome'],
  ['acte de naissance', 'Acte de naissance'],
  ['acte', 'Acte officiel'],
  ['passeport', 'Passeport'],
  ['passport', 'Passeport'],
  ['visa', 'Demande de visa officiel'],
  ['titre de sejour', 'Titre de sejour'],
  ['contrat', 'Contrat']
];
const subjectLower = subject.toLowerCase();
const matched = typeTriggers.find(([kw]) => subjectLower.includes(kw));
const typeDocument = matched ? matched[1] : 'Document scanne recu par email';

return [{
  json: {
    piece_jointe_binary_key: firstAttachmentKey,
    nb_pieces_jointes: binaryKeys.length,
    email_expediteur: fromEmail,
    nom_expediteur: fromName,
    sujet_email: subject,
    type_document_detecte: typeDocument,
    email_message_id: json.messageId || json.uid || ('EMAIL-' + Date.now())
  },
  binary
}];

const item = $input.first();
const key = item.json.piece_jointe_binary_key;
const binaryData = key ? item.binary[key] : null;

if (!binaryData) {
  throw new Error('Aucune piece jointe exploitable trouvee dans cet email.');
}

const mimeType = binaryData.mimeType || 'application/pdf';

return [{
  json: {
    ...item.json,
    ocr_mime_type: mimeType,
    ocr_base64: binaryData.data,
    ocr_is_pdf: mimeType.includes('pdf'),
    ocr_filename: binaryData.fileName || 'document_scanne'
  }
}];

